mapper.select:
SELECT
    crf.*,
    sbc.name AS branch_company_name,
    reimburser.name AS reimburser_name,
    written_by.name AS written_by_name,
    cp.name AS project_name,
    cet.name AS expense_type_name,
    sd.name AS dept_name
FROM contract_reimbursement_fee crf
LEFT JOIN sys_branch_company sbc ON sbc.bool_delete_enum = FALSE AND sbc.id = crf.branch_company_id
LEFT JOIN sys_user reimburser ON reimburser.bool_delete_enum = FALSE AND reimburser.id = crf.reimburser_id
LEFT JOIN sys_user written_by ON written_by.bool_delete_enum = FALSE AND written_by.id = crf.written_by_id
LEFT JOIN contract_expense_type cet ON cet.bool_delete_enum = FALSE AND cet.id = crf.expense_type_id
LEFT JOIN contract_project cp ON cp.bool_delete_enum = FALSE AND cp.id = crf.project_id
LEFT JOIN sys_department sd ON sd.bool_delete_enum = FALSE AND sd.id = crf.dept_id
WHERE crf.bool_delete_enum = FALSE

    AND date_format(crf.reimbursement_date, '%Y-%m-%d') >= #{startDate}


    AND date_format(crf.reimbursement_date, '%Y-%m-%d') <= #{endDate}


    AND crf.branch_company_id = #{branchCompanyId}


    AND crf.dept_id = #{deptId}


    AND crf.expense_type_id = #{expenseTypeId}


    AND crf.project_id = #{projectId}


    
    AND reimburser.name like #{reimburserNameLike}


    
    AND written_by.name like #{writtenByNameLike}
